// The city's texts (city.js) in Croatian, as the sentences take them: server in the genitive ("Poslužitelj grada
// Brna ne odgovara"), dataName in the nominative ("… trenutačno ne odgovara"), dataShort in the genitive ("prema
// podacima grada Brna i OSM-a"), techMap in the nominative after "Učitava se …" (lower case), name in the accusative
// after "za" in rulesHead.
const lower = (s) => s.charAt(0).toLowerCase() + s.slice(1);
const own = (name, of, map, data, parking, credit) => ({
  server: of, dataName: map, dataShort: `${data} i OSM-a`, techMap: lower(map),
  parkingSource: parking, rulesHead: `Širine prema praškom Priručniku IPR-a (C.2), za ${name} orijentacijski:`, credit,
});
const NATIONAL = "Tehnička karta ČÚZK-a";
const TECH_PARKING = "parkirališta iz tehničke karte";
const RUIAN = "RÚIAN © ČÚZK, 2026 (CC BY 4.0, prilagođeno)";
// Outside the Czech Republic (city.js abroad): no technical map, OSM only.
